**op_host/xxx.cpp（TilingFunc + 注册）**
```cpp
namespace optiling {
constexpr uint32_t CORE_NUM = 8;
constexpr uint32_t TILE_NUM = 16;
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    AddCustomTilingData tiling;
    uint32_t totalLength = context->GetInputShape(0)->GetOriginShape().GetShapeSize();
    uint32_t blockLength = totalLength / CORE_NUM;
    uint32_t tileLength  = blockLength / TILE_NUM;

    context->SetBlockDim(CORE_NUM);
    tiling.set_totalLength(totalLength);
    tiling.set_blockLength(blockLength);
    tiling.set_tileNum(TILE_NUM);
    tiling.set_tileLength(tileLength);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t* ws = context->GetWorkspaceSizes(1);
    ws[0] = 0;
    return ge::GRAPH_SUCCESS;
}
} // namespace optiling

// 注册（Tiling下沉场景用 DEVICE_IMPL_OP_OPTILING；普通工程化实践中为 IMPL_OP_OPTILING）
// IMPL_OP_OPTILING(AddCustom).Tiling(TilingFunc);
